from __future__ import annotations

from pathlib import Path
import json
import shutil
import subprocess

from .models import Lab
from .lab_scaffolds import ensure_course_scaffold


def ensure_lab_workspace(root: Path, lab: Lab) -> Path:
    target = root / lab.id
    target.mkdir(parents=True, exist_ok=True)

    # Replace only guides generated by the former mock scaffold. Keep them as
    # archived copies so a learner's notes are never discarded.
    _preserve_legacy_guide(target / "README.md", ("Obiettivi Creativi & Bonus XP", "Angular Standalone Component simulato"))
    _preserve_legacy_guide(target / "SOLUTION.md", ("Angular Standalone reattiva guidata", "Bonus XP"))
    readme = target / "README.md"
    if not readme.exists():
        requirements = "\n".join(f"- [ ] {item}" for item in lab.requirements)
        rubric = "\n".join(f"- {item}" for item in lab.rubric)
        creative = ""
        if lab.creative_goals:
            creative = "\n\n## Estensioni facoltative\n" + "\n".join(f"- {item}" for item in lab.creative_goals)
        readme.write_text(
            f"# {lab.title}\n\n{lab.description}\n\n"
            "Questo workspace contiene uno starter da completare. I test automatici verificano soltanto i comportamenti dichiarati dai test presenti; leggi anche i criteri e controlla manualmente i requisiti che non sono coperti.\n\n"
            "## Requisiti\n\n" f"{requirements}\n\n## Criteri di qualità\n\n{rubric}{creative}\n\n"
            "## Avvio e test\n\n"
            "Installa le dipendenze dal pulsante **Installa dipendenze** nell'app. Poi usa **Esegui test**.\n"
            "Per il server: `dotnet test Tests/Server.Tests.csproj`. Per Angular: `npm test`.\n",
            encoding="utf-8",
        )

    if lab.workspace_template in {"dotnet", "angular", "monorepo"}:
        solution = target / "SOLUTION.md"
        if not solution.exists():
            solution.write_text(
                f"# Guida di lavoro — {lab.title}\n\n"
                "Questa pagina non contiene la soluzione completa. Usala come mappa mentre implementi i requisiti.\n\n"
                "1. Leggi il README e individua un requisito verificabile alla volta.\n"
                "2. Avvia la suite corrispondente e annota il primo errore utile.\n"
                "3. Implementa il comportamento minimo, poi aggiungi un caso limite.\n"
                "4. Ripeti i test e confronta il risultato con i criteri di qualità.\n\n"
                "Un test verde è una prova circoscritta: non certifica da solo accessibilità, sicurezza, chiarezza o completezza del progetto.\n",
                encoding="utf-8",
            )

    if lab.workspace_template in {"dotnet", "angular", "monorepo"}:
        ensure_course_scaffold(target, lab)
    elif lab.workspace_template == "react":
        _ensure_react_project(target, lab)
    else:
        _ensure_plain_project(target, lab)

    return target


def _preserve_legacy_guide(path: Path, markers: tuple[str, ...]) -> None:
    if not path.is_file():
        return
    text = path.read_text(encoding="utf-8", errors="replace")
    if not any(marker in text for marker in markers):
        return
    destination = path.with_name(f"{path.stem}-legacy{path.suffix}")
    suffix = 2
    while destination.exists():
        destination = path.with_name(f"{path.stem}-legacy-{suffix}{path.suffix}")
        suffix += 1
    path.rename(destination)


def _ensure_plain_project(target: Path, lab: Lab) -> None:
    solution = target / "solution.js"
    if not solution.exists():
        solution.write_text(
            "// DEV//48 — descrivi prima input, output e casi limite.\n\nexport function solve(input) {\n  // TODO\n  return input;\n}\n",
            encoding="utf-8",
        )
    test = target / "solution.test.js"
    if not test.exists():
        test.write_text(
            "import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { solve } from './solution.js';\n\ntest('gestisce una lista vuota', () => {\n  assert.deepEqual(solve([]), []);\n});\n\ntest('restituisce soltanto gli elementi attivi senza mutare input', () => {\n  const input = [{id:1, active:true}, {id:2, active:false}];\n  const snapshot = structuredClone(input);\n  assert.deepEqual(solve(input), [{id:1, active:true}]);\n  assert.deepEqual(input, snapshot);\n});\n",
            encoding="utf-8",
        )
    package = target / "package.json"
    if not package.exists():
        package.write_text(json.dumps({"type":"module","scripts":{"test":"node --test"}}, indent=2), encoding="utf-8")
    solution_guide = target / "SOLUTION.md"
    if not solution_guide.exists():
        solution_guide.write_text(
            "# Soluzione commentata\n\nAprila dopo almeno due tentativi reali.\n\n"
            "```js\nexport function solve(input) {\n  if (!Array.isArray(input)) throw new TypeError('input deve essere un array');\n  return input.filter(item => item.active === true);\n}\n```\n\n"
            "`filter` crea un nuovo array, quindi l'input non viene mutato. Il controllo iniziale rende esplicito il contratto della funzione. Aggiungeresti poi i requisiti specifici del brief mantenendo test piccoli e indipendenti.\n",
            encoding="utf-8",
        )


