def open_vscode(path: Path) -> tuple[bool, str]:
    code = shutil.which("code")
    if not code:
        return False, f"VS Code CLI non trovato. Apri manualmente: {path}"
    subprocess.Popen([code, str(path)], cwd=path)
    return True, f"Aperto in VS Code: {path}"


def install_lab_dependencies(path: Path) -> tuple[bool, str]:
    outputs = []
    success = True

    # Se c'è cartella server con .csproj/.sln, esegui dotnet restore
    if (path / "server").exists() or any(path.glob("*.csproj")) or any(path.glob("*.sln")):
        dotnet = shutil.which("dotnet")
        target_dir = path / "server" if (path / "server").exists() else path
        if dotnet:
            test_project = target_dir / "Tests" / "Server.Tests.csproj"
            restore_target = str(test_project) if test_project.is_file() else "."
            proc = subprocess.run([dotnet, "restore", restore_target], cwd=target_dir, capture_output=True, text=True, timeout=120, encoding="utf-8", errors="replace")
            outputs.append(f"[dotnet restore]\n{proc.stdout}\n{proc.stderr}")
            if proc.returncode != 0:
                success = False

    # Se c'è client con package.json o root con package.json, esegui npm install
    client_dir = path / "client" if (path / "client").exists() else path
    if (client_dir / "package.json").exists():
        npm = shutil.which("npm")
        if npm:
            proc = subprocess.run([npm, "install"], cwd=client_dir, capture_output=True, text=True, timeout=300, encoding="utf-8", errors="replace")
            outputs.append(f"[npm install]\n{proc.stdout}\n{proc.stderr}")
            if proc.returncode != 0:
                success = False

    if not outputs:
        return False, "Nessun gestore dipendenze rilevato (né dotnet né npm)."

    return success, ("\n\n".join(outputs))[-8000:]
